    func testTableNestedChainNotMisclassifiedAsLayout() throws {
        // A straight chain of one-nested-table-per-cell tables renders as pipe tables, not a broken layout list
        let _options = try HtmlToMarkdown.conversionOptionsFromJson("{}")
        let result = try HtmlToMarkdown.convert(html: "<table><tr><td><table><tr><td><table><tr><td>leaf</td></tr></table></td></tr></table></td></tr></table>", options: _options)
        XCTAssertTrue(result.content != nil, "expected non-empty value")
        XCTAssertTrue((result.content ?? "").contains("leaf"), "expected to contain: \("leaf")")
        XCTAssertTrue((result.content ?? "").contains("| ---"), "expected to contain: \("| ---")")
    }

    func testTableNestedInSingleCellRendersSeparately() throws {
        // A table nested in a single-cell row renders as its own table
        let _options = try HtmlToMarkdown.conversionOptionsFromJson("{}")
        let result = try HtmlToMarkdown.convert(html: "<table><tr><th>Summary</th></tr><tr><td>Before<table><tr><th>Item</th><th>Amount</th></tr><tr><td>Alpha</td><td>10</td></tr></table></td></tr></table>", options: _options)
        XCTAssertTrue((result.content ?? "").contains("| Item  | Amount |"), "expected to contain: \("| Item  | Amount |")")
        XCTAssertTrue((result.content ?? "").contains("| Alpha | 10     |"), "expected to contain: \("| Alpha | 10     |")")
        XCTAssertFalse((result.content ?? "").contains("\\|"), "expected NOT to contain: \("\\|")")
    }

    func testTableNestedInWrapperRendersSeparately() throws {
