        XCTAssertTrue((result.content ?? "").contains("Before"), "expected to contain: \("Before")")
        XCTAssertFalse((result.content ?? "").contains("\\|"), "expected NOT to contain: \("\\|")")
    }

    func testTableNoThead() throws {
